RMAN> BACKUP DATABASE PLUS ARCHIVELOG;
-- plain full backup, not part of an incremental strategy

RMAN> BACKUP INCREMENTAL LEVEL 0 DATABASE;
-- physically identical, but registered as a baseline
-- for later level 1 incrementals

RMAN> BACKUP INCREMENTAL LEVEL 1 DATABASE;
-- differential (default): since the last level 0 or 1

RMAN> BACKUP INCREMENTAL LEVEL 1 CUMULATIVE DATABASE;
-- cumulative: since the last level 0, regardless of
-- any level 1s taken since
